    'about.version': 'Toleo',

    // ── Mwongozo wa Mtumiaji ────────────────────────────────────────────────
    'guide.title': 'Jinsi ya kutumia Adventist Life',
    'guide.subtitle': 'Ziara fupi ya yote unayoweza kufanya',
    'guide.intro': 'Ni mgeni hapa? Mwongozo huu unakupitisha katika kila sehemu ya programu — jinsi ya kushiriki, kusikiliza, kuungana na kuabudu pamoja. Soma kutoka juu, au rukia sehemu unayoihitaji.',
    'guide.feed.title': 'Mtiririko wa Jamii',
    'guide.feed.body': 'Mtiririko ni ratiba ya jamii yako. Gusa kitufe cha + kuchapisha picha, video na ushuhuda, kisha penda, toa maoni na uhifadhi vinavyoshirikiwa na wengine. Fuata wanajamii kuona machapisho yao zaidi, gusa wasifu kufungua ukurasa wao, na uvute chini kupata mapya.',
    'guide.music.title': 'Muziki na Nyimbo',
    'guide.music.body': 'Vinjari nyimbo na vitabu vya nyimbo kutoka kichupo cha Muziki. Gusa wimbo wowote kufungua kicheza cha skrini nzima, weka vipendwa kwenye foleni, na tengeneza orodha za kucheza za kurudi. Uchezaji unaendelea unapotumia sehemu nyingine za programu, na vipendwa vyako huhifadhiwa kwenye akaunti yako.',
    'guide.communities.title': 'Jumuiya',
    'guide.communities.body': 'Jumuiya ni mahali watu hukutana — kanisa, kwaya, duara la habari, au chochote unachoanzisha mwenyewe. Vinjari kwa aina au tafuta, kisha omba kujiunga na moja kufungua gumzo lake la faragha. Ndani unaweza kutuma ujumbe, picha, hati na ujumbe wa sauti kwa wakati halisi, kuitikia kwa emoji, kutelezesha ujumbe kujibu, na kutafuta gumzo zima. Wasimamizi wanaweza kubandika ujumbe, kuongeza wasimamizi na kusimamia wanachama. Kuanzisha yako mwenyewe kunahitaji jina na aina — na kama hakuna aina inayofaa, unaweza kuunda hiyo pia.',
    'guide.groups.title': 'Vikundi',
    'guide.groups.body': 'Tengeneza au jiunge na vikundi vya mapendeleo kwa funzo la Biblia, vijana, maombi na zaidi. Vikundi vina gumzo kamili la wakati halisi lenye viashiria vya kuandika, nani yupo mtandaoni, ujumbe uliobandikwa na kumbukumbu za shughuli. Vikundi vya faragha vinaweza kuuliza swali kabla ya kumruhusu mtu, na wasimamizi huchagua nani anaruhusiwa kuchapisha.',
    'guide.messages.title': 'Ujumbe wa Moja kwa Moja',
    'guide.messages.body': 'Gusa mwanajamii kuanza mazungumzo ya faragha. Ujumbe wa moja kwa moja unasaidia maandishi, picha, faili na ujumbe wa sauti, unaonyesha wakati ujumbe wako umesomwa, na unakuwezesha kujibu na kuitikia kama gumzo za vikundi.',
    'guide.live.title': 'Matukio ya Moja kwa Moja',
    'guide.live.body': 'Tazama ibada na matukio yanayorushwa moja kwa moja, au wewe mwenyewe anza kurusha moja kwa moja kwa jamii. Jiunge na chumba cha moja kwa moja kutazama na kuzungumza kwa wakati halisi.',
    'guide.bible.title': 'Biblia na Machapisho',
    'guide.bible.body': 'Soma Maandiko, vitabu vya nyimbo na machapisho mengine ndani ya programu. Fuatilia maendeleo yako ya kusoma, weka alama sura za kurudi baadaye, na penda machapisho unayoyaona ya msaada.',
    'guide.market.title': 'Soko',
    'guide.market.body': 'Vinjari na ununue kutoka soko la jamii — ongeza bidhaa kwenye rukwama au orodha ya matakwa na ulipe kwa usalama. Unataka kuuza? Fungua dashibodi ya Muuzaji kuorodhesha bidhaa zako na kufuatilia oda.',
    'guide.notices.title': 'Ubao wa Matangazo',
    'guide.notices.body': 'Ubao wa Matangazo hubeba matangazo rasmi kwa kila mtu. Uangalie kwa habari, matukio na taarifa muhimu kutoka jamii.',
    'guide.account.title': 'Akaunti na Mipangilio Yako',
    'guide.account.body': 'Gusa wasifu wako kuhariri maelezo yako na kuona machapisho yako. Katika Mipangilio unaweza kubadilisha kati ya Kiingereza na Kiswahili, kuchagua hali ya mwanga au giza, kudhibiti arifa na kudhibiti faragha yako — kila kitu husawazishwa kwenye akaunti yako.',
    'guide.footerTip': 'Kidokezo: fungua menyu wakati wowote kutoka aikoni ya ☰ kwenye kona ya juu ili kuruka kati ya vipengele.',

